parameters.text:
You read receipts for an expense claim. Look at the image and return ONLY a JSON object with these keys:
{"is_receipt": true or false, "merchant": "shop or restaurant name", "date": "YYYY-MM-DD of the purchase", "total": number (grand total actually paid, including tax and tip), "currency": "3-letter ISO code, infer from symbol or country", "tax": number (VAT / sales tax shown, 0 if none), "category": one of Meals | Travel | Transport | Accommodation | Office | Software | Other, "payment_method": "card | cash | other", "items": "short description of what was bought, max 100 characters", "confidence": 0-100}
Rules: copy numbers exactly as printed; if a value is not visible use "" or 0; never guess a merchant; if the picture is not a receipt set is_receipt to false. No markdown, no explanations.

parameters.jsCode:
// Turn the model's answer into clean expense fields and combine them with the Telegram submission.
// Everything the model returns is normalised here (dates in several formats, amounts with , or ., currency symbols),
// so the policy step downstream works with plain values and never sees raw model text.
const CATEGORIES = ["Meals","Travel","Transport","Accommodation","Office","Software","Other"];
const sub = $('Prepare Submission Data').item.json;
const raw = $input.item.json;
let text = raw.content ?? raw.text ?? raw.output ?? '';
if (Array.isArray(text)) text = text.map(p => (p && (p.text || p.content)) || '').join('\n');
text = String(text ?? '');

let ai = {};
const fenced = text.match(/\{[\s\S]*\}/);
if (fenced) { try { ai = JSON.parse(fenced[0]); } catch (e) { ai = {}; } }

const toNumber = (v) => {
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
  let s = String(v ?? '').replace(/[^\d.,-]/g, '');
  if (!s) return 0;
  if (/^-?\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(s)) s = s.replace(/\./g, '');   // 1.250,00 -> 1250,00
  else if (/^-?\d{1,3}(,\d{3})+(\.\d{1,2})?$/.test(s)) s = s.replace(/,/g, ''); // 1,250.00 -> 1250.00
  s = s.replace(/,(\d{1,2})$/, '.$1').replace(/,/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : 0;
};
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12 };
const pad = (n) => String(n).padStart(2, '0');
const toIsoDate = (v) => {
  const s = String(v ?? '').trim();
  let m;
  if ((m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/))) return m[1] + '-' + pad(m[2]) + '-' + pad(m[3]);
  if ((m = s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/))) {                 // dd.mm.yyyy (or mm/dd/yyyy when the first number cannot be a month)
    let d = +m[1], mo = +m[2]; if (mo > 12 && d <= 12) [d, mo] = [mo, d];
    return m[3] + '-' + pad(mo) + '-' + pad(d);
  }
  if ((m = s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2})$/))) { let d = +m[1], mo = +m[2]; if (mo > 12 && d <= 12) [d, mo] = [mo, d]; return '20' + m[3] + '-' + pad(mo) + '-' + pad(d); }
  if ((m = s.match(/^(\d{1,2})\s+([A-Za-z]{3,})\.?\s+(\d{4})/)) && MONTHS[m[2].slice(0, 4).toLowerCase()] !== undefined) return m[3] + '-' + pad(MONTHS[m[2].slice(0, 4).toLowerCase()] || MONTHS[m[2].slice(0, 3).toLowerCase()]) + '-' + pad(m[1]);
  if ((m = s.match(/^([A-Za-z]{3,})\.?\s+(\d{1,2}),?\s+(\d{4})/)) && MONTHS[m[1].slice(0, 3).toLowerCase()] !== undefined) return m[3] + '-' + pad(MONTHS[m[1].slice(0, 3).toLowerCase()]) + '-' + pad(m[2]);
  const d = new Date(s);
  return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
};
const SYMBOLS = { '€': 'EUR', '$': 'USD', '£': 'GBP', 'kr': 'NOK', 'zł': 'PLN', '₴': 'UAH', 'chf': 'CHF' };
const toCurrency = (v) => {
  const s = String(v ?? '').trim();
  if (/^[A-Za-z]{3}$/.test(s)) return s.toUpperCase();
  for (const [sym, code] of Object.entries(SYMBOLS)) if (s.toLowerCase().includes(sym)) return code;
  return '';
};
const key = (v) => String(v ?? '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();

const merchant = String(ai.merchant ?? '').trim().slice(0, 80);
const date = toIsoDate(ai.date);
const total = toNumber(ai.total);
const currency = toCurrency(ai.currency) || 'EUR';
const catRaw = String(ai.category ?? '').trim().toLowerCase();
const category = CATEGORIES.find(c => c.toLowerCase() === catRaw) || CATEGORIES.find(c => catRaw && c.toLowerCase().startsWith(catRaw.slice(0, 4))) || 'Other';
const isReceipt = ai.is_receipt !== false && ai.is_receipt !== 'false';
const confidence = Math.max(0, Math.min(100, Math.round(Number(ai.confidence) || 0)));
const today = new Date(); const todayUtc = Date.UTC(today.getFullYear(), today.getMonth(), today.getDate());
const ageDays = date ? Math.round((todayUtc - Date.parse(date + 'T00:00:00Z')) / 86400000) : null;

const missing = [];
if (!isReceipt) missing.push('not a receipt');
if (!merchant) missing.push('merchant');
if (!date) missing.push('date');
if (!(total > 0)) missing.push('total');

return { json: {
  ...sub,
  merchant, date, total, currency, tax: toNumber(ai.tax), category, category_key: key(category),
  payment_method: String(ai.payment_method ?? '').trim().toLowerCase().slice(0, 20),
  description: [sub.caption, String(ai.items ?? '').trim()].filter(Boolean).join(' - ').slice(0, 200),
  is_receipt: isReceipt, ai_confidence: confidence, age_days: ageDays,
  missing_fields: missing.join(', '),
  receipt_key: sub.user_id + '|' + key(merchant) + '|' + date + '|' + total.toFixed(2),
} };

