// Monthly expense report: approved expenses of the previous calendar month, totals per employee and per category,
// one HTML email. Set MONTH to "2026-08" to rebuild an older month by hand.
const MONTH = ''; // '' = previous month
const MAX_ROWS = 200;

const now = new Date();
const prev = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
const month = MONTH || prev.toISOString().slice(0, 7);
const toNumber = (v) => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').replace(/[^\d.,-]/g, '');
  if (/^-?\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(s)) s = s.replace(/\./g, '');   // 1.250,00 -> 1250,00
  else if (/^-?\d{1,3}(,\d{3})+(\.\d{1,2})?$/.test(s)) s = s.replace(/,/g, ''); // 1,250.00 -> 1250.00
  const n = Number(s.replace(/,(\d{1,2})$/, '.$1').replace(/,/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const money = (n) => (Math.round(n * 100) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const monthOf = (r) => {
  const m = String(r.Month ?? '').trim();
  if (/^\d{4}-\d{2}$/.test(m)) return m;
  const d = String(r.Date ?? r.SubmittedAt ?? '').trim();
  if (/^\d{4}-\d{2}/.test(d)) return d.slice(0, 7);
  if (typeof r.Date === 'number') return new Date(Date.UTC(1899, 11, 30) + Math.round(r.Date) * 86400000).toISOString().slice(0, 7); // Sheets serial date
  return '';
};

const rows = [];
for (const { json: r } of $input.all()) {
  if (!r || !String(r.Merchant ?? '').trim()) continue;
  if (!/^\s*approved\s*$/i.test(String(r.Status ?? ''))) continue;
  if (monthOf(r) !== month) continue;
  const amount = Math.round(toNumber(r.Amount) * 100) / 100;
  if (amount <= 0) continue;
  rows.push({ employee: String(r.Employee ?? '').trim() || 'unknown', merchant: String(r.Merchant).trim(), date: String(r.Date ?? '').trim().slice(0, 10), amount,
    currency: String(r.Currency ?? '').trim().toUpperCase() || '?', category: String(r.Category ?? '').trim() || 'Other', description: String(r.Description ?? '').trim() });
}
rows.sort((a, b) => a.employee.localeCompare(b.employee) || a.date.localeCompare(b.date));

const sumBy = (keyFn) => { const t = {}; for (const r of rows) { const k = keyFn(r); t[k] = t[k] || { count: 0, sums: {} }; t[k].count++; t[k].sums[r.currency] = (t[k].sums[r.currency] || 0) + r.amount; } return t; };
const fmtSums = (sums) => Object.keys(sums).sort().map(c => money(sums[c]) + ' ' + c).join(', ') || '-';
const byEmployee = sumBy(r => r.employee), byCategory = sumBy(r => r.category);
const totals = {}; for (const r of rows) totals[r.currency] = (totals[r.currency] || 0) + r.amount;

if (!rows.length) {
  return [{ json: { month, subject: 'Expense report ' + month + ': no approved expenses', html: '<p>No approved expenses were recorded for ' + month + '.</p>', expense_count: 0, totals: {} } }];
}
const table = (title, obj) => '<h3>' + title + '</h3><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>' + title.split(' ')[1] + '</th><th>Receipts</th><th>Total</th></tr>' +
  Object.keys(obj).sort().map(k => '<tr><td>' + esc(k) + '</td><td style="text-align:right">' + obj[k].count + '</td><td>' + esc(fmtSums(obj[k].sums)) + '</td></tr>').join('') + '</table>';
const detail = rows.slice(0, MAX_ROWS).map(r => '<tr><td>' + esc(r.employee) + '</td><td>' + esc(r.date) + '</td><td>' + esc(r.merchant) + '</td><td>' + esc(r.category) + '</td><td style="text-align:right">' + money(r.amount) + ' ' + esc(r.currency) + '</td><td>' + esc(r.description) + '</td></tr>').join('');
const html = '<h2>Expense report ' + month + '</h2><p><b>' + rows.length + '</b> approved receipt(s), total <b>' + esc(fmtSums(totals)) + '</b></p>' +
  table('By employee', byEmployee) + table('By category', byCategory) +
  '<h3>All receipts' + (rows.length > MAX_ROWS ? ' (first ' + MAX_ROWS + ')' : '') + '</h3><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Employee</th><th>Date</th><th>Merchant</th><th>Category</th><th>Amount</th><th>Description</th></tr>' + detail + '</table>' +
  '<p style="color:#666">Generated by the n8n expense workflow from the Expenses tab. Receipt photos are in the finance Telegram chat.</p>';

return [{ json: { month, subject: 'Expense report ' + month + ': ' + rows.length + ' receipt(s), ' + fmtSums(totals), html, expense_count: rows.length, totals, by_employee: byEmployee } }];
